<script setup>
import {computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import InvestmentCurves from './InvestmentCurves.vue'
const route=useRoute(),router=useRouter()
const tabs=[{id:'funding',label:'基金投入',file:'funding.html',title:'基金支持如何覆盖技术方向',description:'按执行年份观察在研项目的批准经费规模，查看七大技术方向的配置。'},{id:'outputs',label:'论文与专利',file:'outputs.html',title:'科研与技术成果如何逐年积累',description:'切换论文与专利，沿发表年份和申请年份查看成果的方向与规模。'},{id:'terms',label:'70 个技术点',file:'funding-terms.html',title:'从七大方向，展开到具体技术',description:'沿共同技术词表，查看各个技术点的投入与成果变化。'},{id:'curves',label:'投入产出曲线',file:'curves.html',title:'把投入与成果放在同一时间轴上',description:'七大技术方向分开观察，切换相对趋势或原始数值，比较变化节奏。'}]
const active=computed(()=>tabs.find(t=>t.id===route.query.analysis)||tabs[0])
const termOutputs=computed(()=>route.query.measure==='outputs')
const file=computed(()=>active.value.id==='terms'&&termOutputs.value?'output-terms.html':active.value.file)
const src=computed(()=>'/chain-analysis/v1/'+file.value)
function choose(id){router.replace({query:{...route.query,analysis:id,measure:undefined}})}
</script>
<template><div class="investment-module"><header><p class="kicker">人工智能 · 投入与产出</p><h2>{{active.title}}</h2><p>{{active.description}}</p></header><div class="view-tools"><nav aria-label="投入与产出分析"><button v-for="t in tabs" :key="t.id" :class="{active:active.id===t.id}" @click="choose(t.id)">{{t.label}}</button></nav><a v-if="active.id!=='curves'" :href="src" target="_blank" rel="noopener">独立展示 ↗</a></div><div v-if="active.id==='terms'" class="measure"><button :class="{active:!termOutputs}" @click="router.replace({query:{...route.query,measure:'funding'}})">基金投入</button><button :class="{active:termOutputs}" @click="router.replace({query:{...route.query,measure:'outputs'}})">论文与专利</button></div><div :key="file" class="pane-swap"><InvestmentCurves v-if="active.id==='curves'"/><div v-else class="embedded-report" :class="{terms:active.id==='terms'}"><iframe :key="file" :src="src" :title="active.title" allow="fullscreen" allowfullscreen></iframe></div></div><details class="measure-note"><summary>图表口径与阅读方式</summary><p v-if="active.id==='funding'">在研项目批准经费：项目在执行期内的各年，以其批准金额展示资助覆盖规模；跨技术方向按原分析规则分摊。图中金额对应在研项目规模。</p><p v-else-if="active.id==='outputs'">论文以发表年份、专利以申请年份组织。七大类使用已核验的展示版本，累计篇数与专利数量分别计算。</p><p v-else-if="active.id==='curves'">在研项目经费、当年论文与当年专利按各自时间字段统计。相对趋势将每条曲线的峰值设为 100，用于观察时间位置与变化；原始数值保留各自单位。具体样本范围见图内说明。</p><p v-else>70 技术点沿用人工智能共同词表，色深表现该技术点在各年份的投入或成果规模。</p></details></div></template>
<style scoped>
.investment-module header{margin:32px 0 24px}.kicker{color:#ae0d28!important;font-size:13px!important;letter-spacing:1.3px;font-weight:600}.investment-module h2{font-size:32px;line-height:1.45;margin:10px 0 12px;color:#2d2a28}.investment-module header p{color:#817a74;font-size:16px;line-height:1.8}.view-tools{display:flex;justify-content:space-between;align-items:center;gap:12px;border-bottom:1px solid #ded9d4;margin-bottom:22px}.view-tools nav{display:flex;gap:24px;flex-wrap:wrap}.view-tools button{background:none;border:0;border-bottom:3px solid transparent;color:#78716c;font-size:17px;padding:12px 2px 16px;cursor:pointer}.view-tools button.active{color:#ae0d28;border-bottom-color:#ae0d28;font-weight:700}.view-tools a{font-size:14px;color:#8c1d34;white-space:nowrap;text-decoration:none}.embedded-report{background:#fff;border:1px solid #e6e1dc;border-radius:15px;overflow:hidden}.embedded-report iframe{display:block;width:100%;height:850px;border:0;background:#fafaf9}.embedded-report.terms iframe{height:880px}.measure{display:flex;gap:10px;margin:0 0 16px}.measure button{border:1px solid #ded8d2;background:#fff;color:#78716c;padding:8px 16px;border-radius:6px;cursor:pointer}.measure button.active{border-color:#ae0d28;color:#ae0d28}.measure-note{color:#817a74;font-size:13px;margin:18px 0;line-height:1.9}.measure-note summary{cursor:pointer}.measure-note p{max-width:850px}@media(max-width:700px){.investment-module h2{font-size:25px}.view-tools{align-items:flex-start}.view-tools nav{gap:14px}.view-tools button{font-size:14px}.view-tools a{margin-top:15px;font-size:12px}.embedded-report iframe{height:1100px}}
</style>
